def input_features(self, seq: torch.Tensor) -> torch.Tensor:
    emb = self.item_emb(seq)
    earlier_matches = seq.unsqueeze(2).eq(seq.unsqueeze(1)).tril(diagonal=-1)
    counts = earlier_matches.sum(dim=-1).masked_fill(seq.eq(0), 0)
    scale = 1.0 + 0.1 * counts.clamp(max=5).to(torch.float32).log1p()
    return self.dropout(emb * scale.to(emb.dtype).unsqueeze(-1))

